#!/bin/bash
# Second EVALUATION of the three Qwen3-8B ablation attackers (rebuttal, 2026-11-13). Each arm has ONE trained attacker; this re-runs
# jobs/eval_attacker_ckpts.sbatch on the same 20 checkpoints with a new run name, so the adversarial prompts are re-generated by the
# attacker and the target is re-sampled. It measures evaluation noise for a fixed attacker -- it is NOT a second attacker training.
# Target settings are those of the original evals (banners in slurm_logs/rlh_eval_iclr_rlh_ablq8_*): think / append per arm.
# Phase 1 evaluates the last five checkpoints of every arm (Final / Last-5 first), phase 2 the remaining fifteen. Resumable.
# usage (inside a 1-GPU allocation): bash injecAgent-rl-harmmer/rl-injector/jobs/reeval_ablq8.sh [suffix, default eval2]
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
SUF=${1:-eval2}
L=$ROOT/LLaMA-Factory/saves/qwen3-8b/lora
STATE="$ROOT/slurm_logs/reeval_ablq8_${SUF}.state"; : > "$STATE"
say(){ echo "[$(date '+%F %T')] $*" | tee -a "$STATE"; }
# run | lora | SYS_APPEND | TARGET_THINK
ARMS=(
 "iclr_rlh_ablq8_nolast_yyy|$L/abl_q8_nolast_v2_sft_8k_r64_GA4_qkvo_3epoch_5e-6|1|1"
 "iclr_rlh_ablq8_yyn|$L/abl_q8_nothink_v2_sft_8k_r64_GA4_qkvo_3epoch_5e-6|0|1"
 "iclr_rlh_ablq8_ynn|$L/abl_q8_nothink_v2_sft_8k_r64_GA4_qkvo_3epoch_5e-6|0|0"
)
cd "$ROOT"
say "START suffix=$SUF job=${SLURM_JOB_ID:-}"
for phase in "816 867 918 969 1020" ""; do
  for arm in "${ARMS[@]}"; do
    IFS='|' read -r RUN LORA APP THINK <<<"$arm"
    say "EVAL $RUN phase=${phase:-rest} begin"
    env TARGET=sr_qwen SYS_APPEND=$APP TARGET_THINK=$THINK SR_LORA="$LORA" RUN_NAME="${RUN}_${SUF}" CKPT_DIR="checkpoints/$RUN" CKPT_ONLY="$phase" \
      bash injecAgent-rl-harmmer/rl-injector/jobs/eval_attacker_ckpts.sbatch
    say "EVAL $RUN phase=${phase:-rest} end rc=$?"
  done
  say "PHASE ${phase:-rest} done"
done
say "DONE"
